<?php $schedules = query('SELECT * FROM weekly_schedules WHERE doctor_id=? ORDER BY weekday', [$doctor['id']])->fetchAll(); ?>
<article class="doctor-card"><div class="doctor-portrait"><img src="<?= e(doctor_photo($doctor)) ?>" alt="<?= e($doctor['name']) ?>" loading="lazy"><span class="portrait-label"><?= e(t('Hospital specialist')) ?></span></div><div class="doctor-card-body"><span class="eyebrow"><?= e(t($doctor['specialization'])) ?></span><h3><?= e($doctor['name']) ?></h3><p class="qualifications"><?= e($doctor['qualifications']) ?></p><div class="doctor-schedule"><?php if ($schedules): ?><?php foreach ($schedules as $s): ?><div><span><?= e(weekday_label((int)$s['weekday'],true)) ?></span><strong><?= e(time_label($s['consultation_start'])) ?></strong></div><?php endforeach; ?><?php else: ?><span><?= e(t('Schedule to be announced')) ?></span><?php endif; ?></div><a class="btn btn-outline-primary w-100" href="<?= e(url('book.php?doctor=' . $doctor['id'])) ?>"><?= e(t('Book appointment')) ?> <span aria-hidden="true">↗</span></a></div></article>
